    ('杭州', '雷峰塔', 'fe39dc6f54c2cd07', 1, 'https://assets.kakarot8.com/city-opt/hangzhou/commons-49832170.webp', 1600, 1067, 'https://assets.kakarot8.com/city-opt/hangzhou/commons-49832170.mobile.webp', 800, 533, 'https://assets.kakarot8.com/city-opt/hangzhou/commons-49832170.mobile.webp', 400, 267, '雷峰塔实景图', 'seed_5cities_v1')
) AS img(city, place_name, asset_id, pos, d_url, d_w, d_h, m_url, m_w, m_h, t_url, t_w, t_h, alt_text, batch_id)
  ON img.city = c.city AND img.place_name = c.canonical_name
ON CONFLICT (place_id, position) DO UPDATE
SET asset_id = EXCLUDED.asset_id,
    desktop_url = EXCLUDED.desktop_url,
    mobile_url = EXCLUDED.mobile_url,
    thumb_url = EXCLUDED.thumb_url,
    alt_text = EXCLUDED.alt_text,
    active = TRUE;

COMMIT;
